from collections import deque


def openLock(deadends, target):
    dead = [False] * 10000
    for d in deadends:
        dead[d] = True
    if dead[0] or dead[target]:
        return -1
    if target == 0:
        return 0
    dist = [-1] * 10000
    dist[0] = 0
    queue = deque([0])
    while queue:
        cur = queue.popleft()
        for p in (1, 10, 100, 1000):
            digit = cur // p % 10
            base = cur - digit * p
            for nd in ((digit + 1) % 10, (digit + 9) % 10):
                nxt = base + nd * p
                if dist[nxt] == -1 and not dead[nxt]:
                    dist[nxt] = dist[cur] + 1
                    if nxt == target:
                        return dist[nxt]
                    queue.append(nxt)
    return -1
